#include <vector>
#include <queue>

class Solution {
public:
    int maxCandies(std::vector<int>& status, std::vector<int>& candies, std::vector<std::vector<int>>& keys, std::vector<std::vector<int>>& containedBoxes, std::vector<int>& initialBoxes) {
        int n = status.size();
        std::vector<bool> hasBox(n, false), hasKey(n, false), opened(n, false);
        std::queue<int> q;
        for (int b : initialBoxes) {
            hasBox[b] = true;
            if (status[b] == 1) {
                q.push(b);
                opened[b] = true;
            }
        }
        int totalCandies = 0;
        while (!q.empty()) {
            int b = q.front();
            q.pop();
            totalCandies += candies[b];
            for (int k : keys[b]) {
                hasKey[k] = true;
                if (hasBox[k] && !opened[k]) {
                    opened[k] = true;
                    q.push(k);
                }
            }
            for (int cb : containedBoxes[b]) {
                hasBox[cb] = true;
                if ((status[cb] == 1 || hasKey[cb]) && !opened[cb]) {
                    opened[cb] = true;
                    q.push(cb);
                }
            }
        }
        return totalCandies;
    }
};

import java.util.*;

class Solution {
    public int maxCandies(int[] status, int[] candies, int[][] keys, int[][] containedBoxes, int[] initialBoxes) {
        int n = status.length;
        boolean[] hasBox = new boolean[n];
        boolean[] hasKey = new boolean[n];
        boolean[] opened = new boolean[n];
        Queue<Integer> q = new LinkedList<>();
        for (int b : initialBoxes) {
            hasBox[b] = true;
            if (status[b] == 1) {
                q.offer(b);
                opened[b] = true;
            }
        }
        int totalCandies = 0;
        while (!q.isEmpty()) {
            int b = q.poll();
            totalCandies += candies[b];
            for (int k : keys[b]) {
                hasKey[k] = true;
                if (hasBox[k] && !opened[k]) {
                    opened[k] = true;
                    q.offer(k);
                }
            }
            for (int cb : containedBoxes[b]) {
                hasBox[cb] = true;
                if ((status[cb] == 1 || hasKey[cb]) && !opened[cb]) {
                    opened[cb] = true;
                    q.offer(cb);
                }
            }
        }
        return totalCandies;
    }
}

